{"command":"cd /[REDACTED:secret.entropy]-tryout-office; cat > /tmp/e2b_verify.mjs <<'EOF'
import { Sandbox } from 'e2b'
const sbx = await Sandbox.create('agentclash-tryout-office', { timeoutMs: 120000 })
try {
  for (const cmd of [
    'codex --version',
    'node --version',
    'python3 --version',
    'pandoc --version | head -1',
    'python3 -c "import openpyxl, docx, pptx, pypdf, reportlab, pandas; print(\'pylibs OK\')"',
    'soffice --version 2>/dev/null | head -1 || echo "soffice present check"',
  ]) {
    const r = await sbx.commands.run(cmd, { timeoutMs: 60000 })
    console.log(`$ ${cmd}\n${(r.stdout || r.stderr).trim()}\n`)
  }
} finally { await sbx.kill() }
EOF
E2B_API_KEY=$(grep -h E2B_API_KEY ~/.e2b 2>/dev/null | cut -d= -f2); node --version >/dev/null
npm ls e2b >/dev/null 2>&1 || (cd /tmp && npm i e2b >/dev/null 2>&1)
cd /tmp && node e2b_verify.mjs 2>&1 | tail -40","description":"Verify tools inside the built sandbox","timeout":200000}

