        <form
          onSubmit={(event) => {
            event.preventDefault();
            void send();
          }}
          className="mt-3 flex items-end gap-2 rounded-2xl border border-[#f4efe6]/12 bg-[#16140f]/80 p-2 focus-within:border-[#d8a15d]/40"
