              }
            }}
            rows={1}
            placeholder="Reply to the agent…"
            className="block max-h-32 w-full resize-none bg-transparent px-2 py-1.5 text-sm text-[#f4efe6] outline-none placeholder:text-[#f4efe6]/30"
