680	function buildInput(
681	  fields: [string, FieldSpec][],
682	  required: Set<string>,
683	  values: Record<string, string>,
684	): { value: Record<string, unknown> } | { error: string } {
685	  const input: Record<string, unknown> = {};
686	  for (const [field, spec] of fields) {
687	    const raw = (values[field] ?? "").trim();
688	    if (!raw) {
689	      if (required.has(field)) {
690	        return { error: `${fieldLabel(field)} is required.` };
691	      }
692	      continue;
693	    }
694	    if (spec.type === "integer" || spec.type === "number") {
695	      const value = Number(raw);
696	      if (!Number.isFinite(value)) {
697	        return { error: `${fieldLabel(field)} must be a number.` };
698	      }
699	      if (spec.minimum !== undefined && value < spec.minimum) {
700	        return { error: `${fieldLabel(field)} must be at least ${spec.minimum}.` };
701	      }
702	      if (spec.maximum !== undefined && value > spec.maximum) {
703	        return { error: `${fieldLabel(field)} must be at most ${spec.maximum}.` };
704	      }
705	      input[field] = spec.type === "integer" ? Math.trunc(value) : value;
706	    } else {
707	      input[field] = raw;
708	    }
709	  }
710	  return { value: input };
711	}
