726	function downloadTrace(tryout: AgentTryout, events: TryoutTimelineEvent[]) {
727	  const payload = {
728	    source: "agentclash_public_tryout",
729	    exported_at: new Date().toISOString(),
730	    tryout,
731	    events,
732	  };
733	  const blob = new Blob([JSON.stringify(payload, null, 2)], {
734	    type: "application/json",
735	  });
736	  const url = URL.createObjectURL(blob);
737	  const link = document.createElement("a");
738	  link.href = url;
739	  link.download = `agentclash-tryout-${tryout.id}.json`;
740	  document.body.appendChild(link);
741	  link.click();
742	  link.remove();
743	  URL.revokeObjectURL(url);
744	}
